YANDEX_VERIFICATION = "1b8d9b18395784b5"

JSON_SERVICE_FIELDS = {"tasks", "hero_badges", "uses", "scope", "stages", "limitations", "specs"}


def _settings(conn: sa.Connection) -> None:
    rows = conn.execute(sa.text("SELECT id, value FROM site_settings WHERE key = 'site'")).mappings().all()
    for row in rows:
        value = dict(row["value"])
        changed = False
        for item in DATA["settings"]:
            current = value.get(item["key"])
            # Партнёр: из 0005 там лежит полное описание студии — оставляем только название и ссылку
            if item["key"] == "partner" and isinstance(current, dict) and current.get("about"):
                value["partner"] = {"name": current.get("name") or "OBLIQ", "url": current.get("url") or ""}
                changed = True
            elif current == item["old"] or (item["key"] == "socials" and not current):
                value[item["key"]] = item["new"]
                changed = True
        # Подтверждение прав в Яндекс Вебмастере — если код ещё не задан в CMS
        seo = dict(value.get("seo") or {})
        if not seo.get("yandex_verification"):
            seo["yandex_verification"] = YANDEX_VERIFICATION
            value["seo"] = seo
            changed = True
        if changed:
            conn.execute(
                sa.text("UPDATE site_settings SET value = CAST(:value AS jsonb) WHERE id = :id"),
                {"value": json.dumps(value, ensure_ascii=False), "id": row["id"]},
            )


def _pages(conn: sa.Connection) -> None:
    for item in DATA["pages"]:
        rows = (
            conn.execute(
                sa.text("SELECT id, sections, body_html, seo_description FROM pages WHERE slug = :slug"),
                {"slug": item["slug"]},
            )
            .mappings()
            .all()
        )
        for row in rows:
            if item["kind"] == "section":
                sections = dict(row["sections"])
                if sections.get(item["key"]) != item["old"]:
                    continue
                sections[item["key"]] = item["new"]
                conn.execute(
                    sa.text("UPDATE pages SET sections = CAST(:s AS jsonb), updated_at = now() WHERE id = :id"),
                    {"s": json.dumps(sections, ensure_ascii=False), "id": row["id"]},
                )
            elif row[item["key"]] == item["old"]:
                conn.execute(
                    sa.text(f"UPDATE pages SET {item['key']} = :v, updated_at = now() WHERE id = :id"),  # noqa: S608
                    {"v": item["new"], "id": row["id"]},
                )


def _service(conn: sa.Connection) -> None:
    service = DATA["service"]
    rows = (
        conn.execute(
            sa.text("SELECT id, locale FROM services WHERE slug = 'it-resheniya' AND summary = :old"),
            {"old": service["old_summary"]},
        )
        .mappings()
        .all()
    )
    for row in rows:
        params: dict[str, object] = {"id": row["id"]}
        assignments = []
        for field, value in service["fields"].items():
            if field in JSON_SERVICE_FIELDS:
                assignments.append(f"{field} = CAST(:{field} AS jsonb)")
                params[field] = json.dumps(value, ensure_ascii=False)
            else:
                assignments.append(f"{field} = :{field}")
                params[field] = value
        query = f"UPDATE services SET {', '.join(assignments)}, updated_at = now() WHERE id = :id"  # noqa: S608
        conn.execute(sa.text(query), params)
        conn.execute(sa.text("DELETE FROM faq_items WHERE service_id = :id"), {"id": row["id"]})
        for order, (question, answer) in enumerate(service["faq"]):
            conn.execute(
                sa.text(
                    "INSERT INTO faq_items (locale, question, answer, sort_order, is_published, service_id) "
                    "VALUES (:locale, :q, :a, :order, true, :id)"
                ),
                {"locale": row["locale"], "q": question, "a": answer, "order": order, "id": row["id"]},
            )


def _faq(conn: sa.Connection) -> None:
    for item in DATA["faq"]:
        conn.execute(
            sa.text("UPDATE faq_items SET answer = :new WHERE question = :q AND answer = :old AND service_id IS NULL"),
            {"q": item["question"], "old": item["old"], "new": item["new"]},
        )


OLD_DESCRIPTION = (
    "Проектирование, изготовление и монтаж металлоконструкций, внутренняя отделка помещений "
    "и организация доставки инженерного оборудования."
)
NEW_DESCRIPTION = (
    "«Росметстрой» — металлоконструкции под ключ: проектирование, изготовление и монтаж, "
    "отделка помещений, логистика оборудования. Москва, тел. 8 800 600-84-77."
)


def _description(conn: sa.Connection) -> None:
    """Описание для поисковиков с названием и телефоном — по полю, а не всем блоком SEO."""
    rows = conn.execute(sa.text("SELECT id, value FROM site_settings WHERE key = 'site'")).mappings().all()
    for row in rows:
        value = dict(row["value"])
        seo = dict(value.get("seo") or {})
        if seo.get("default_description", "") in ("", OLD_DESCRIPTION):
            seo["default_description"] = NEW_DESCRIPTION
            value["seo"] = seo
            conn.execute(
                sa.text("UPDATE site_settings SET value = CAST(:value AS jsonb) WHERE id = :id"),
                {"value": json.dumps(value, ensure_ascii=False), "id": row["id"]},
            )
    conn.execute(
        sa.text(
            "UPDATE pages SET seo_description = :new, updated_at = now() "
            "WHERE slug = 'home' AND seo_description IN ('', :old)"
        ),
        {"new": NEW_DESCRIPTION, "old": OLD_DESCRIPTION},
    )


def upgrade() -> None:
    conn = op.get_bind()
    _description(conn)
    _settings(conn)
    _pages(conn)
    _service(conn)
    _faq(conn)


def downgrade() -> None:
    # Данные не откатываются
    pass
